<script setup>
import {ref,onMounted,onBeforeUnmount,watch} from 'vue';const props=defineProps({background:Object,color:String,playing:Boolean});const host=ref();let ctx,observer,frame,last=0,width=0,height=0,points=[];const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
function resize(){const r=host.value.parentElement.getBoundingClientRect();width=Math.max(1,r.width);height=Math.max(1,r.height);const ratio=Math.min(devicePixelRatio,1.5);host.value.width=width*ratio;host.value.height=height*ratio;ctx.setTransform(ratio,0,0,ratio,0,0);points=Array.from({length:Math.min(100,Math.max(10,props.background.density||50))},(_,i)=>({x:((Math.sin(i*43.7)*4253.2)%1+1)%1*width,y:((Math.cos(i*29.4)*3451.7)%1+1)%1*height,r:1+(i%3)*.4,vx:(i%2?1:-1)*(.06+i%4*.02),vy:(i%3-1)*.08}));draw(0,true);}
function draw(now,once=false){if(!once)frame=requestAnimationFrame(draw);if(!ctx||(!once&&(document.hidden||((!props.playing||reduced)&&last>0)||now-last<40)))return;const delta=last?Math.min(50,now-last):16;last=now;ctx.clearRect(0,0,width,height);const type=props.background.type,color=props.color||'#6ce5c0';ctx.strokeStyle=color;ctx.fillStyle=color;ctx.globalAlpha=props.background.opacity??.35;if(['plain','grid'].includes(type))return;for(let i=0;i<points.length;i++){const p=points[i];if(props.playing&&!reduced){p.x=(p.x+p.vx*delta/16*(props.background.speed||.5)+width)%width;p.y=(p.y+p.vy*delta/16*(props.background.speed||.5)+height)%height;}ctx.beginPath();if(type==='bokeh'){const gradient=ctx.createRadialGradient(p.x,p.y,0,p.x,p.y,14+p.r*10);gradient.addColorStop(0,color+'30');gradient.addColorStop(1,color+'00');ctx.fillStyle=gradient;ctx.arc(p.x,p.y,14+p.r*10,0,Math.PI*2);}else{ctx.fillStyle=color;ctx.arc(p.x,p.y,p.r*.6,0,Math.PI*2);}ctx.fill();if(type==='mesh'){for(let j=i+1;j<points.length;j++){const q=points[j],d=Math.hypot(q.x-p.x,q.y-p.y);if(d<width*.13){ctx.globalAlpha=(1-d/(width*.13))*.07*(props.background.opacity||.35);ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(q.x,q.y);ctx.lineWidth=.6;ctx.stroke();}}ctx.globalAlpha=props.background.opacity??.35;}if(type==='lines'&&i%5===0){ctx.globalAlpha=.1;ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(p.x+width*.09,p.y-width*.06);ctx.stroke();ctx.globalAlpha=props.background.opacity??.35;}}}
onMounted(()=>{ctx=host.value.getContext('2d');observer=new ResizeObserver(resize);observer.observe(host.value.parentElement);resize();frame=requestAnimationFrame(draw);});watch(()=>props.background.density,()=>{if(ctx)resize();});onBeforeUnmount(()=>{cancelAnimationFrame(frame);observer?.disconnect();});
</script>
<template><canvas ref="host" class="aw-particles" aria-hidden="true"></canvas></template>
